      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          if (image) ...<Widget>[
            Container(
              height: 76,
              decoration: BoxDecoration(
                color: p.surface2,
                borderRadius: BorderRadius.circular(10),
              ),
              child: Center(
                  child: Icon(Icons.image_outlined, size: 26, color: p.muted)),
            ),
            const SizedBox(height: 8),
